1	// Exportación del listado mensual de facturas a CSV (REQ-003).
2	//
3	// La exportación es un ESPEJO: selecciona, ordena y serializa; no recalcula ningún
4	// importe (CA-06), no corrige incoherencias de la entrada (CA-07) y no altera los
5	// textos (CA-15). Devuelve la cadena CSV; no escribe en disco.
6	'use strict';
7	
8	// --- Contrato de la salida ------------------------------------------------
9	
10	// Sitio único de las columnas de la exportación (CA-01, CA-14). Orden y nombres
11	// son DE CONTRATO: cambiarlos exige ADR y write-back.
12	const COLUMNAS = Object.freeze(['id', 'fecha', 'cliente', 'descripcion', 'monto', 'comision', 'total']);
13	
14	// Campos de importe, según la «Forma mínima de una factura» del REQ.
15	const CAMPOS_IMPORTE = Object.freeze(['monto', 'comision', 'total']);
16	
17	const SEPARADOR = ',';
18	const DELIMITADOR = '"';
19	const FIN_DE_REGISTRO = '\r\n'; // CRLF, de contrato (RFC 4180, CA-02)
20	const DECIMALES_MINIMOS = 2; // de contrato (CA-08)
21	
22	const FORMA_FECHA = /^\d{4}-\d{2}-\d{2}$/;
23	const NOTACION_EXPONENCIAL = /^(\d+)(?:\.(\d+))?e([+-]\d+)$/i;
24	
25	// --- Utilidades de diagnóstico -------------------------------------------
26	
27	/**
28	 * Describe un valor para un mensaje de error sin volcar su contenido cuando es
29	 * un objeto: los mensajes nombran la factura y el campo (CA-17/CA-18), no los
30	 * datos del cliente, que no tienen por qué acabar en un log.
31	 */
32	function describirValor(valor) {
33	  if (valor === null) return 'null';
34	  const tipo = typeof valor;
35	  if (tipo === 'number' || tipo === 'boolean' || tipo === 'undefined') return String(valor);
36	  return tipo;
37	}
38	
39	/** Nombra la factura por su `id`; si el `id` falta, por su posición (CA-17). */
40	function describirFactura(factura, indice) {
41	  const id = factura.id;
42	  return typeof id === 'string' && id !== ''
43	    ? `la factura "${id}"`
44	    : `la factura en la posición ${indice}`;
45	}
46	
47	// --- Formato de los valores ----------------------------------------------
48	
49	function rellenar(numero, ancho) {
50	  return String(numero).padStart(ancho, '0');
51	}
52	
53	/**
54	 * Texto `AAAA-MM-DD` de la fecha de emisión (CA-10).
55	 *
56	 * De un `Date` se toman los componentes UTC: es la única lectura que no depende
57	 * de la zona horaria del proceso, de modo que la misma entrada produce la misma
58	 * salida en cualquier máquina (CA-13) y ninguna conversión de zona desplaza el día.
59	 */
60	function textoDeFecha(valor, sujeto) {
61	  if (typeof valor === 'string') {
62	    if (!FORMA_FECHA.test(valor)) {
63	      throw new Error(`${sujeto}: el campo "fecha" no tiene la forma AAAA-MM-DD`);
64	    }
65	    return valor;
66	  }
67	  if (valor instanceof Date) {
68	    if (Number.isNaN(valor.getTime())) {
69	      throw new Error(`${sujeto}: el campo "fecha" es un Date inválido`);
70	    }
71	    const anio = valor.getUTCFullYear();
72	    if (anio < 0 || anio > 9999) {
73	      throw new Error(`${sujeto}: el campo "fecha" tiene un año que no cabe en AAAA-MM-DD`);
74	    }
75	    return `${rellenar(anio, 4)}-${rellenar(valor.getUTCMonth() + 1, 2)}-${rellenar(valor.getUTCDate(), 2)}`;
76	  }
77	  throw new Error(`${sujeto}: el campo "fecha" debe ser una cadena AAAA-MM-DD o un Date (recibido: ${describirValor(valor)})`);
78	}
79	
80	/**
81	 * Representación decimal posicional de un número finito, sin exponente.
82	 *
83	 * Parte de `String(numero)`, que es la representación más corta que vuelve al
84	 * mismo valor, y sólo reubica el punto: así el texto emitido releído con
85	 * `Number` es `===` al valor de entrada (CA-08), sin truncar ni redondear.
86	 */
87	function aPosicional(numero) {
88	  let texto = String(numero);
89	  let signo = '';
90	  if (texto.startsWith('-')) {
91	    signo = '-';
92	    texto = texto.slice(1);
93	  }
94	  const exponencial = NOTACION_EXPONENCIAL.exec(texto);
95	  if (exponencial === null) return signo + texto;
96	
97	  const [, entera, fraccionaria = '', exponente] = exponencial;
98	  const digitos = entera + fraccionaria;
99	  const punto = entera.length + Number(exponente);
100	  if (punto >= digitos.length) return signo + digitos + '0'.repeat(punto - digitos.length);
101	  if (punto <= 0) return `${signo}0.${'0'.repeat(-punto)}${digitos}`;
102	  return `${signo + digitos.slice(0, punto)}.${digitos.slice(punto)}`;
103	}
104	
105	/** Rellena con ceros a la derecha hasta el mínimo de decimales (no altera el valor). */
106	function conDecimalesMinimos(texto) {
107	  const punto = texto.indexOf('.');
108	  if (punto === -1) return `${texto}.${'0'.repeat(DECIMALES_MINIMOS)}`;
109	  const decimales = texto.length - punto - 1;
110	  return decimales >= DECIMALES_MINIMOS ? texto : texto + '0'.repeat(DECIMALES_MINIMOS - decimales);
111	}
112	
113	/** Celda de un importe (CA-08, CA-09); falla si no es un número finito (CA-18). */
114	function textoDeImporte(valor, sujeto, campo) {
115	  if (typeof valor !== 'number' || !Number.isFinite(valor)) {
116	    throw new Error(`${sujeto}: el campo "${campo}" debe ser un número finito (recibido: ${describirValor(valor)})`);
117	  }
118	  return conDecimalesMinimos(aPosicional(valor));
119	}
120	
121	function textoObligatorio(valor, sujeto, campo, noVacia) {
122	  if (typeof valor !== 'string' || (noVacia && valor === '')) {
123	    throw new Error(`${sujeto}: el campo "${campo}" debe ser una cadena${noVacia ? ' no vacía' : ''} (recibido: ${describirValor(valor)})`);
124	  }
125	  return valor;
126	}
127	
128	/** `descripcion` es el único campo opcional; ausente o vacío se emite como celda vacía (CA-16). */
129	function textoDeDescripcion(valor, sujeto) {
130	  if (valor === undefined || valor === null || valor === '') return '';
131	  if (typeof valor !== 'string') {
132	    throw new Error(`${sujeto}: el campo "descripcion" debe ser una cadena (recibido: ${describirValor(valor)})`);
133	  }
134	  return valor;
135	}
136	
137	// --- Serialización CSV ----------------------------------------------------
138	
139	/** Entrecomillado incondicional con la comilla interna duplicada (CA-03). */
140	function entrecomillar(texto) {
141	  return DELIMITADOR + texto.split(DELIMITADOR).join(DELIMITADOR + DELIMITADOR) + DELIMITADOR;
142	}
143	
144	function construirLinea(celdas) {
145	  return celdas.map((celda) => entrecomillar(celda)).join(SEPARADOR);
146	}
147	
148	// --- Orden ----------------------------------------------------------------
149	
150	/** Comparación por punto de código Unicode (CA-13), no por unidad UTF-16. */
151	function compararPorPuntoDeCodigo(a, b) {
152	  const puntosA = Array.from(a);
153	  const puntosB = Array.from(b);
154	  const comunes = Math.min(puntosA.length, puntosB.length);
155	  for (let i = 0; i < comunes; i += 1) {
156	    const puntoA = puntosA[i].codePointAt(0);
157	    const puntoB = puntosB[i].codePointAt(0);
158	    if (puntoA !== puntoB) return puntoA < puntoB ? -1 : 1;
159	  }
160	  return puntosA.length - puntosB.length;
161	}
162	
163	function compararFilas(a, b) {
164	  const porFecha = compararPorPuntoDeCodigo(a.fecha, b.fecha);
165	  if (porFecha !== 0) return porFecha;
166	  const porId = compararPorPuntoDeCodigo(a.id, b.id);
167	  if (porId !== 0) return porId;
168	  // Desempate final por la línea ya serializada: sin él, dos facturas con la
169	  // misma fecha y el mismo id saldrían en el orden de llegada y CA-13 exige
170	  // cadenas idénticas byte a byte para cualquier orden de llegada.
171	  return compararPorPuntoDeCodigo(a.linea, b.linea);
172	}
173	
174	// --- Validación de los argumentos ----------------------------------------
175	
176	function validarPeriodo(anio, mes) {
177	  if (!Number.isInteger(anio)) {
178	    throw new Error(`el argumento "anio" debe ser un entero (recibido: ${describirValor(anio)})`);
179	  }
180	  if (!Number.isInteger(mes) || mes < 1 || mes > 12) {
181	    throw new Error(`el argumento "mes" debe ser un entero entre 1 y 12 (recibido: ${describirValor(mes)})`);
182	  }
183	}
184	
185	// --- Punto de entrada -----------------------------------------------------
186	
187	/**
188	 * Construye la fila de una factura seleccionada, validando sus campos.
189	 * Sólo se emiten las columnas del sitio único CA-01: cualquier propiedad
190	 * adicional del objeto de entrada se ignora (CA-14).
191	 */
192	function construirFila(factura, sujeto, fecha) {
193	  const valores = {
194	    id: textoObligatorio(factura.id, sujeto, 'id', true),
195	    fecha,
196	    cliente: textoObligatorio(factura.cliente, sujeto, 'cliente', false),
197	    descripcion: textoDeDescripcion(factura.descripcion, sujeto),
198	  };
199	  for (const campo of CAMPOS_IMPORTE) {
200	    valores[campo] = textoDeImporte(factura[campo], sujeto, campo);
201	  }
202	  return {
203	    fecha,
204	    id: valores.id,
205	    linea: construirLinea(COLUMNAS.map((columna) => valores[columna])),
206	  };
207	}
208	
209	/**
210	 * Exporta a CSV (RFC 4180) las facturas del año y mes indicados.
211	 *
212	 * @param {Array<object>} facturas listado de facturas (de cualquier mes)
213	 * @param {number} anio año entero
214	 * @param {number} mes mes entero entre 1 y 12
215	 * @returns {string} cadena CSV con el encabezado y una línea por factura del mes
216	 * @throws {Error} si los argumentos o alguna factura exportable no cumplen la
217	 *   forma contratada en REQ-003; en ese caso no se devuelve ninguna salida.
218	 */
219	function exportarFacturasACsv(facturas, anio, mes) {
220	  if (!Array.isArray(facturas)) {
221	    throw new Error(`el argumento "facturas" debe ser un arreglo (recibido: ${describirValor(facturas)})`);
222	  }
223	  validarPeriodo(anio, mes);
224	
225	  const filas = [];
226	  for (let indice = 0; indice < facturas.length; indice += 1) {
227	    const factura = facturas[indice];
228	    if (factura === null || typeof factura !== 'object') {
229	      throw new Error(`la factura en la posición ${indice} no es un objeto de factura (recibido: ${describirValor(factura)})`);
230	    }
231	    const sujeto = describirFactura(factura, indice);
232	    // La fecha se comprueba en todas las facturas porque sin ella no se puede
233	    // decidir a qué mes pertenecen; las de otro mes se excluyen en silencio (CA-11).
234	    const fecha = textoDeFecha(factura.fecha, sujeto);
235	    if (Number(fecha.slice(0, 4)) !== anio || Number(fecha.slice(5, 7)) !== mes) continue;
236	    filas.push(construirFila(factura, sujeto, fecha));
237	  }
238	
239	  filas.sort(compararFilas);
240	
241	  const lineas = [construirLinea(COLUMNAS)];
242	  for (const fila of filas) lineas.push(fila.linea);
243	  return lineas.map((linea) => linea + FIN_DE_REGISTRO).join('');
244	}
245	
246	module.exports = { exportarFacturasACsv };
