21	function factura(cambios) {
22	  return {
23	    id: 'F-001',
24	    fecha: '2026-09-10',
25	    cliente: 'ACME',
26	    descripcion: 'servicio',
27	    monto: 100,
28	    comision: 2,
29	    total: 102,
30	    ...cambios,
31	  };
32	}
