40	/** Analizador CSV conforme a RFC 4180 (CA-04): campos entrecomillados, `""` escapado, registros CRLF. */
41	function analizarCsv(texto) {
42	  const registros = [];
43	  let registro = [];
44	  let campo = '';
45	  let dentro = false;
46	  let i = 0;
47	  while (i < texto.length) {
48	    const caracter = texto[i];
49	    if (dentro) {
50	      if (caracter === '"') {
51	        if (texto[i + 1] === '"') {
52	          campo += '"';
53	          i += 2;
54	          continue;
55	        }
56	        dentro = false;
57	        i += 1;
58	        continue;
59	      }
60	      campo += caracter;
61	      i += 1;
62	      continue;
63	    }
64	    if (caracter === '"') {
65	      dentro = true;
66	      i += 1;
67	      continue;
68	    }
69	    if (caracter === ',') {
70	      registro.push(campo);
71	      campo = '';
72	      i += 1;
73	      continue;
74	    }
75	    if (caracter === '\r' && texto[i + 1] === '\n') {
76	      registro.push(campo);
77	      registros.push(registro);
78	      registro = [];
79	      campo = '';
80	      i += 2;
81	      continue;
82	    }
83	    campo += caracter;
84	    i += 1;
85	  }
86	  if (campo !== '' || registro.length > 0) {
87	    registro.push(campo);
88	    registros.push(registro);
89	  }
90	  return registros;
91	}
92	
93	/** Celda de una columna en la primera línea de datos. */
94	function celda(csv, columna) {
95	  return analizarCsv(csv)[1][COLUMNAS.indexOf(columna)];
96	}
97	
98	function celdasTodasEntrecomilladas(texto) {
99	  let dentro = false;
100	  for (let i = 0; i < texto.length; i += 1) {
101	    const caracter = texto[i];
102	    if (caracter === '"') {
103	      dentro = !dentro;
104	      continue;
105	    }
106	    if (dentro) continue;
107	    if (caracter === ',') continue;
108	    if (caracter === '\r' && texto[i + 1] === '\n') {
109	      i += 1;
110	      continue;
111	    }
112	    return false; // carácter desnudo fuera de un campo entrecomillado
113	  }
114	  return !dentro;
115	}
116	
117	function hayLfSueltoFueraDeCampo(texto) {
118	  let dentro = false;
119	  for (let i = 0; i < texto.length; i += 1) {
120	    const caracter = texto[i];
121	    if (caracter === '"') {
122	      dentro = !dentro;
123	      continue;
124	    }
125	    if (!dentro && caracter === '\n' && texto[i - 1] !== '\r') return true;
126	  }
127	  return false;
128	}
